package com.bank.reconcile;

import java.util.logging.Logger;

// Finds the single missing cheque serial for National Bank of India.
public class ReconciliationService {
    private static final Logger log = Logger.getLogger(ReconciliationService.class.getName());

    // Sum method. serials holds 1..N with exactly one missing; length = N-1.
    public long missingBySum(int[] serials) {
        long n = serials.length + 1L;               // N = count + 1
        long expected = n * (n + 1) / 2;            // long math avoids overflow
        long actual = 0;
        for (int s : serials) {
            actual += s;                            // accumulate actual total
        }
        long missing = expected - actual;
        log.info(() -> "missingBySum: expected=" + expected + " actual=" + actual
                + " missing=" + missing);
        return missing;
    }

    // XOR method. Cannot overflow; present numbers cancel in pairs.
    public int missingByXor(int[] serials) {
        int n = serials.length + 1;
        int acc = 0;
        for (int i = 1; i <= n; i++) acc ^= i;      // XOR full range 1..N
        for (int s : serials) acc ^= s;             // XOR present serials
        final int missing = acc;                    // survivor is the missing one
        log.info(() -> "missingByXor: missing=" + missing);
        return missing;
    }
}
