package com.bank.reconcile;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: find the missing cheque serial both ways.
public class ReconcileDemo {
    private static final Logger log = Logger.getLogger(ReconcileDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        ReconciliationService service = new ReconciliationService();

        // Rajesh's cheque serials 1..8 processed, serial 5 is outstanding.
        int[] processed = {1, 2, 3, 4, 6, 7, 8};
        long bySum = service.missingBySum(processed);
        int byXor = service.missingByXor(processed);

        log.info(() -> "Missing cheque serial (sum) = " + bySum);
        log.info(() -> "Missing cheque serial (xor) = " + byXor);
        if (bySum == byXor) {
            log.info(() -> "Both methods agree: serial " + bySum + " is outstanding");
        } else {
            log.severe("Methods disagree — data integrity problem");
        }
    }
}
